1	/**
2	 * require-status-matches-coverage — a spec.md / ADR must declare the lifecycle
3	 * status its test links can support, and must declare one the parsers can read.
4	 *
5	 * Status is the org's backlog signal: the web-UI pills render it, spec-status-upkeep
6	 * flips it, humans trust it. This rule makes it answerable to the corpus's own
7	 * `([validated by](test.ts#Lnn))` links rather than to whoever last edited the row:
8	 *
9	 *   no testable statement linked    -> Draft
10	 *   some testable statements linked -> In Progress
11	 *   every testable statement linked -> Shipped
12	 *
13	 * The per-doc complement of `require-statement-links` (which nags per unlinked
14	 * statement); both read the same `statementCoverage` walk, so the two rules can
15	 * never disagree about what is linked. Skips `rejected` / `retired` docs via the
16	 * shared `statusTier`, and docs with no testable statements (no tier to infer).
17	 *
18	 * Which folders hold the corpus comes from the `roots` option
19	 * (`{ spec: ["specs"], adr: ["adrs"] }` by default) — see `lib/status-coverage.mjs`
20	 * for the coverage walk.
21	 *
22	 * Deliberately carries no `fix`/`suggest`: the `format` CI job runs
23	 * `eslint --fix` and commits the result back, so a fixer here would silently
24	 * rewrite spec statuses across the repo on every PR. The message names the label
25	 * to write; a human writes it.
26	 */
27	import { statusLabel } from "./lib/spec-parsers.mjs";
28	import { DOC_ROOTS_SCHEMA, docKind } from "./lib/doc-kind.mjs";
29	import { statusMismatch } from "./lib/status-coverage.mjs";
30	const CORPUS = { spec: "spec", adr: "ADR" };
31	const REQUIREMENT = {
32	    spec: "Add a `| Status | Draft |` row to the header table (one of Draft / In Progress / Shipped / Rejected / Retired).",
33	    adr: "Add `status: draft` to the YAML frontmatter (one of draft / in progress / shipped / rejected / retired).",
34	};
35	function mismatchReport(mismatch, kind) {
36	    const loc = { line: mismatch.line, column: 1 };
37	    if (mismatch.reason === "untagged") {
38	        return {
39	            loc,
40	            messageId: "untagged",
41	            data: { corpus: CORPUS[kind], requirement: REQUIREMENT[kind] },
42	        };
43	    }
44	    return {
45	        loc,
46	        messageId: "statusMismatch",
47	        data: {
48	            corpus: CORPUS[kind],
49	            actual: mismatch.actual,
50	            expected: statusLabel(mismatch.expected, kind),
51	            linked: mismatch.linked,
52	            testable: mismatch.testable,
53	        },
54	    };
55	}
56	export default {
57	    meta: {
58	        type: "problem",
59	        docs: {
60	            description: "require every spec.md / ADR to declare a parseable lifecycle status that matches its test-link coverage: no links -> Draft, some -> In Progress, all -> Shipped. Skips rejected/retired docs and docs with no testable statements.",
61	        },
62	        schema: [
63	            {
64	                type: "object",
65	                properties: { roots: DOC_ROOTS_SCHEMA },
66	                additionalProperties: false,
67	            },
68	        ],
